// ==UserScript==
// @name         [KRISS Portal] 업무 대시보드
// @namespace    kriss.krisstar.tools
// @version      1.26.2
// @description  포털 메인 통합 업무 대시보드. IPMS 단계와 나의업무(BPM)를 연결하고, 소스별 폴백·자동 재조회로 목록을 최신으로 유지. 긴급복구 Alt+Shift+X
// @match        https://krisstar.kriss.re.kr/index.do*
// @match        https://krisstar.kriss.re.kr/
// @grant        GM_getValue
// @grant        GM_setValue
// @grant        GM_xmlhttpRequest
// @grant        unsafeWindow
// @connect      kriss.re.kr
// @run-at       document-idle
// ==/UserScript==

/* v1.26.2: 기관별 소유지분 및 신청번호 기준 PPS 단건 조회로 생성 전 확인. */

/*
 * v1.26.1 (2026-09-08) — 신청완료 후속을 선행조사로 분류, 공통 대상 규칙,
 * 원본 신청일·상세보강, 업무 식별자 기반 연속처리와 닫힘 후 잔존 점검,
 * BPM 진입 전 최신 단계 확인, 제출 결과 미확인 보존, 번호체계 혼용 차단.
 * 기존 변경 이력의 실측·정책 주장은 당시 기록이며 최신 구현은 본 버전을 따른다.
 */

/*
 * v1.25.10 (2026-09-07) — 번호 체계 충돌 오연결 차단 · 묶음 키 교정 (patch, 1.25.9 -> 1.25.10)
 *  [실측 근거] 콘솔 '[PD] BPM 연결 상세': P230024US(표면증강 라만) 청구서 행이 202609-003·202609-004 두 BPM에 동시 연결,
 *    같은 BPM에 P260057KR(능동 조명)·P260080KR(비의도적 이동) 행이 '중복승격 차단'. 사용자 진술: 표면증강 라만을 눌러도
 *    능동 조명·비의도적 이동이 열린다. 업무요청은 서로 다른 제목의 요청(OA제출 보고 / 국내우선권주장 출원완료보고)이
 *    '외 1건'으로 묶였다.
 *  [원인] 청구서번호(rqstNo)·검토요청번호(cnfRqstNo)·지출신청번호(actRqstNo)·업무요청번호·BPM요청번호가 전부
 *    'YYYYMM-NNN' 꼴이다. 후보키를 '단계의 요청번호 계열 전부'로 두었더니 서로 다른 번호 체계의 같은 값이 충돌했다 —
 *    P230024US의 청구서번호 202609-003이 P260057KR 검토 BPM(bizKey=cnfRqstNo 202609-003)에 붙은 것. v1.25.9의 묶음도
 *    'cnfRqstNo || rqstNo'·'bpmRqstNo || rqstNo'로 필드를 섞어 같은 충돌로 다른 요청을 합쳤다. 목록의 이름은 틀리지 않았다.
 *  [교정1·후보키] 각 단계는 BPM 진입 실측 계약의 bizKey 필드 하나만 낸다 — 청구서 cnfRqstNo · 업무요청 bpmRqstNo ·
 *    신청 intellRqstNo(출원은 미실측: 신청번호·출원요청번호). 등록·선행조사는 연결하지 않는다(안전망이 담당).
 *  [교정2·배타 매칭] bizKey로 맞은 행은 같은 업무 객체의 라인이므로 전부 연결한다(청구서의 관리번호별 라인 각각 '내 차례').
 *    배타는 대괄호 토큰(95점) 매칭에만 남긴다. 전역 중복제거 키에 관리번호를 넣어 라인이 서로를 지우지 않게 한다.
 *  [교정3·묶음 키] 업무요청은 rqstNo끼리만, 청구서는 cnfRqstNo끼리·rqstNo끼리만 묶는다(접두어로 체계 분리).
 *    '외 N건'은 이제 '같은 요청번호 아래의 다른 관리번호 라인'일 때만 붙는다.
 *  [진단] 연결·차단 표에 '매칭'(어느 필드=값으로 맞았는지, 토큰 여부)과 rqstNo·cnfRqstNo·actRqstNo·bpmRqstNo 원시값 열 추가.
 *    연결이 줄어든 BPM은 '목록에 없는 나의업무' 표가 아니라 안전망(BPM 직접) 행으로 보인다 — 그 행을 누르면 정확히 그 BPM.
 *  [캐시] pd_cache_v38 → v39(오연결이 저장된 구캐시 폐기). [무변경] 재조회·폴백·정렬 밴드·표시 계층.
 */

/*
 * v1.25.9 (2026-09-07) — 유령 행 제거(요청번호 단위 묶음) · 깜빡임 진정 · 정렬 밴드 · 머리행 1줄 (patch, 1.25.8 -> 1.25.9)
 *  [실측 근거] 2026-09-07 콘솔 '[PD] 중복승격 차단 상세': 청구서 202609-004에 P230024US·P260080KR, 202609-003에
 *    P230024US·P260057KR, 업무요청 202609-013에 P250153KR·P260042KR — 청구서·업무요청 목록은 '요청 1건 = 관리번호 1행'.
 *    같은 로그에서 [PD] 데이터 진단이 수십 회 연속 출력 — 팝업 열고 닫을 때마다 window focus가 재조회·재렌더를 발화.
 *  [교정1·유령 행] 청구서는 cnfRqstNo||rqstNo, 업무요청은 bpmRqstNo||rqstNo 단위로 항목 1개만 만든다(groupBy·groupExtra).
 *    종전엔 행마다 항목을 만들어 같은 BPM을 두 행이 가리켰고, v1.25.4 배타 매칭이 하나만 승격하면서 나머지가
 *    '다른 라벨의 유령 행'(예: '비의도적 이동을 이용한 코히런트…' 청구서 검토중)으로 남았다. 그 행을 누르면 같은
 *    청구서가 열리지만 첫 줄 관리번호가 달라 '매칭되지 않는 건'처럼 보였고, 처리해도 유령은 남았다.
 *    묶음은 부제 '외 N건', 메타 토큰(외 N건 · P…), 툴팁·검색(mngAll)에 모든 관리번호를 싣는다. 라우팅은 첫 행 기준.
 *  [교정2·깜빡임] window 'focus' 리스너 제거(팝업 개폐마다 발화). 목록·탭·칩·흐름 패널은 렌더 서명이 같으면 DOM을
 *    다시 쓰지 않는다(_pdHtml). 팝업 닫힘 재조회는 강제 → 비강제(POPUP_GAP_SEC 15초 간격)로, 진행 중인 조회가
 *    있으면 끝난 뒤 한 번만 이어서 돈다(LOAD_PENDING) — 반영 누락 없이 POST 폭주만 막는다.
 *  [교정3·정렬 밴드] 경과일 항목이 상한 없이 -1000+(100-경과)로 내려가 가장 오래된 한 건이 첫 줄을 영구 점유하고
 *    기한 지난 항목보다 위였다. pdSortKey: A 내 차례(BPM 연결·직접) > B 기한 경과·오늘 > C 경과일(999일 캡) > D 기한 남음.
 *    캐시 복원·승격 뒤에도 전 행 재계산(normalizeModelActions) — D-day도 그때 다시 센다.
 *  [교정4·머리행] 상태 칩(경과·오늘 마감·신규)을 필터 줄 우측으로 이동, 머리행 nowrap + 마스트 축소·말줄임,
 *    '종합 콘솔'→'콘솔', '마지막 갱신 N분 전'→'N분 전'(툴팁에 전체). 항목 수가 많아도 2줄로 꺾이지 않는다.
 *  [교정5·표기] 출원지시 대기 행(routeKind fileInstruction)의 상태가 출원 사전의 04='제출'로 찍히던 오표기 →
 *    '출원지시 대기'(국외는 '· 국외'). 신청 파생 행(ppsCreate·applyReview·ppsDraft)은 신청 사전으로.
 *  [추가·토글] 설정 → 표시 → '국외 출원지시 대기 표시'(pd_fgnfile_v1, 기본 ON). v1.25.8에서 신설된 국외 출원지시
 *    항목은 '출원지시일자 없음 + 출원 목록 없음'을 근거로 하는데, 국외 건의 출원지시가 IPMS 밖에서 처리돼 이 신호가
 *    남는 경우 노이즈가 된다 — 실제 대기 건이 아니면 끄고, 그 사실을 회신하면 판정 근거를 바꾼다.
 *  [캐시] pd_cache_v37 → v38. [무변경] 판별 규칙 · 라우팅 계약 · 소스별 폴백 · 긴급복구.
 */

/*
 * v1.25.8 (2026-09-04) — 캐시 고착·오라우팅·누락 3증상 근본 교정 + 자동 갱신·국외 출원지시 (patch, 1.25.7 -> 1.25.8)
 *  [실측 근거] 2026-09-04 콘솔: '[PD] 데이터 진단' 표 Array(0) — F5 직후 로드가 IPMS를 한 건도 조회하지 않고 캐시만
 *    그렸다. 연결 8건 점수 전부 150·160(+40 확증 0건) — 나의업무 응답 텍스트에 관리번호가 없어 v1.25.5 교차검증이
 *    실제로는 발동하지 않는다. 게이트 '국외제외 22' — 국외 신청이 통째로 빠져 있었다. 사용자 진술: "⟳를 눌러도
 *    순간 바뀌었다가 이전 것으로 덮어씌어진다".
 *  [교정1·재조회 정책] needIpms = force || 캐시 10분 초과 → 항상 재조회. 캐시는 '즉시 그리기'에만 쓴다.
 *    세션 내 REVALIDATE_GAP_SEC(90초) 안의 비강제 호출만 BPM 연결 재계산으로 대신한다.
 *    · 팝업 닫힘(pdAfterPopupClose)·연속 처리 종료/중지 → 1.2초 뒤 재조회(scheduleRefresh).
 *    · 탭 복귀·창 포커스(400ms 합침)·CACHE_MIN(10분) 주기 → 재조회. 종전엔 주기 갱신이 아예 없었다.
 *    · 진행 중인 재조회를 비강제 호출이 끊지 않도록 loadAll 래퍼(LOAD_BUSY) 추가 — beginLoad의 abort로
 *      첫 조회가 취소되고 LAST_IPMS_AT만 갱신되는 구멍을 막는다.
 *  [교정2·소스별 폴백] 6개 소스 중 하나라도 실패하면 새 결과를 전부 폐기하던 규칙(v1.23.3~)을 폐지.
 *    실패 소스만 세션 내 직전 성공분(RAW)으로, 그것도 없으면 캐시 모델의 그 소스 행만 이월(pickCarry →
 *    buildActions(R, carry)). 성공한 소스의 새 데이터는 어떤 경우에도 화면에 반영·저장된다. 이것이
 *    "순간 바뀌었다가 되돌아감"의 정체 — 느린 소스 하나가 목록 전체를 이전 캐시로 되돌렸다.
 *    나의업무 조회 실패도 IPMS 결과를 버리는 사유에서 제외 — 직전 성공분(WORK_OK)으로 연결만 유지.
 *    RAW는 '소스별 마지막 성공 조회분'으로 의미가 바뀐다(흐름 패널은 그대로 동작).
 *  [교정3·catch 경로] buildActions 예외 시 캐시 원본을 다시 적재하며 BPM 재계산을 건너뛰던 분기 제거 —
 *    막 갱신된 화면이 저장 시점의 옛 연결(이미 처리된 myWork 포함)로 되돌아가는 또 하나의 경로였다.
 *  [교정4·매칭] 후보키를 단계별로 한정(STAGE_MATCH_KEYS). 신청번호는 신청·출원 행만 낸다 — 선행조사·등록·
 *    청구서 행이 B_RES00004(instancename=신청번호)를 가로채 '선행조사 진행 · 내 차례' 같은 라벨로 승격되고
 *    클릭 시 신청 BPM이 열리던 통로 차단. 알려진 프로세스는 단계 불일치 시 감점(-35)이 아니라 차단.
 *  [교정5·라우팅] 청구서 04·07 폴백(나의업무에 없는 건)을 myWork·ST0301 고정 → readOnly 실측 계약
 *    (from S_PMS_03015020 · accRqstNo)로 되돌림. 캐시된 상태코드로 남의 차례 건을 처리 화면으로 열던 결함.
 *  [교정6·가드] 전역 가드의 '기한이 조회기간 넘게 지남(dv)' 제외를 progress 한정으로. 종전엔 track을 안 봐서
 *    완료필요일·과제종료일이 3개월 넘게 지난 업무요청·청구서·등록완료 접수(처리할 업무)가 조용히 사라졌다.
 *  [추가·국외 출원지시] 신청 04 국외(cntCls O/M · 관리번호 접미 KR 외)는 선행조사 없이 출원지시로 간다(사용자 확인).
 *    출원요청일 없음 + 출원 목록에 행 없음(10 출원지시전 제외, FILE_IDX)이면 '신청완료 → 출원지시·메일 (국외)'
 *    (stage file · routeKind fileInstruction · action). 라우팅은 KR 출원지시와 동일(S_PMS_03012020 {intellRqstNo}).
 *    ⚠ 가출원·분할·후속·유럽재등록(P/D/S/E)의 KR 건은 미확인이라 종전대로 출원지시를 평가하지 않는다.
 *    ⚠ 신청 목록은 7개월 하한 창 — 그보다 오래된 국외 신청의 출원지시는 이번에도 잡히지 않는다(차기).
 *  [진단] '[PD] 중복승격 차단 상세' 표(밀려난 행 → 승격된 행) · '[PD] 소스 폴백' 줄 · 진단표가 비면 사유 명시.
 *  [캐시] pd_cache_v36 → v37. [무변경] 표시 계층 · 정렬 · 키보드 내비 · 긴급복구 · 바로가기 계약.
 *  [남은 확인] 입력 Helper(별도 스크립트)가 index.do에서 설정 객체 미정의로 2초마다 예외 — 선행조사 미제출 원장
 *    (kriss.pps.draft.v1)이 기록되지 않으면 '작성 필요(미제출)'는 뜨지 않는다. 그 스크립트 점검 필요.
 */

/*
 * v1.25.7 (2026-08-25) — 목록에서 통째로 사라지던 나의업무 복구 (patch, 1.25.6 -> 1.25.7)
 *  [근거] 실측 콘솔(2026-08-25, v1.25.5): 나의업무 16건 · 연결 5건 · 안전망 8건 · 중복승격 차단 1건.
 *    16 − 5 − 8 = 3건이 어느 목록에도 나타나지 않았다.
 *  [원인] addBpmSafetyNet은 patentBpmMeta()가 null을 돌려주면 그 BPM 업무를 조용히 버린다.
 *    patentBpmMeta는 ① BPM_PROCESS_META 코드 매핑 ② 특허 키워드 텍스트 폴백만 본다.
 *    둘 다 걸리지 않는 나의업무(행정 계열 BPM 등)는 IPMS 행과도 연결되지 않으므로 완전히 증발한다.
 *    '처리해야 할 것이 안 뜬다'의 정체다.
 *  [교정1·기타 단계] 특허 키워드에도 안 걸리는 나의업무를 stage 'etc'(기타)로 안전망에 올린다.
 *    라벨은 BPM 업무명(defname)을 그대로 쓰고, 진입은 기존 myWork 경로 그대로다.
 *    탭은 pm·tets와 같은 관례로 해당 건이 있을 때만 합류하고, 정렬은 개인저작물 바로 앞
 *    (ETC_SORT 85000)에 둔다 — 특허 처리 흐름과 축이 다르므로 목록 후미에 모은다.
 *  [교정2·설정] 설정 → 표시 → '나의업무 전체 포함'(pd_allbpm_v1, 기본 ON). 끄면 종전처럼
 *    특허 관련 BPM만 표시한다. 바꾸면 즉시 재조회해 안전망을 다시 계산한다.
 *  [진단] 콘솔에 '[PD] 목록에 없는 나의업무' 표를 추가한다(BPM업무·processcode·instancename·
 *    상태·제목). 이제 이 표가 비어 있어야 정상이며, 남아 있으면 그 행이 왜 빠졌는지 바로 보인다.
 *  [확인·무변경] 같은 로그에서 신청 4건(P260088US·P260089CN·P260090EU·P260091PCT)은 각각
 *    다른 BPM 인스턴스(RESI0099100006~0009)에 1:1로 연결됐다 — 배타 매칭·관리번호 교차검증은
 *    정상 동작 중이며 중복 연결이 아니다. 판별·라우팅·캐시 정책은 손대지 않았다.
 */

/*
 * v1.25.6 (2026-08-25) — 캐시 고착 해소: 보존 사유 재정의 · 하드 만료 · 수동 비우기 (patch, 1.25.5 -> 1.25.6)
 *  [증상] 이미 처리한 건이 목록에서 사라지지 않는다. 새로고침해도 같은 목록이 돌아온다.
 *  [원인·핵심] v1.23.3의 안정화 규칙이 과했다. loadAll은 '경고가 하나라도 있으면 새 조회 결과를
 *    버리고 캐시를 유지'했는데, 그 경고에 부분수신·상한 도달 같은 연성 경고까지 포함돼 있었다.
 *      · truncated       : n < total (부분수신)
 *      · maybeTruncated  : total 불명 + 상한 도달 — 청구서(exp)는 상한이 300건이라
 *                          실제 건수가 300을 넘거나 total이 안 내려오면 매 조회마다 발생한다.
 *    즉 조건이 계속 참이면 캐시는 영구히 갱신되지 않고, 저장(gmSet)도 같은 조건으로 막혀 있어
 *    캐시 시각조차 고정된다 → 처리 완료 건이 계속 남는다. 강제 새로고침(⟳)도 이 분기에 걸린다.
 *  [교정1·보존 사유 한정] 캐시 보존은 '소스가 통째로 없음'(rows 배열 미확보 = 조회 실패·스키마
 *    불일치)과 'BPM 나의업무 조회 실패'로 한정한다(sourceHardFail). 부분수신·상한 도달은
 *    경고로만 남기고 화면과 캐시를 새 결과로 교체한다 — 불완전해도 최신이 낫다.
 *  [교정2·하드 만료] CACHE_MAX_MIN(6시간)을 넘긴 캐시는 표시에도 보존에도 쓰지 않는다.
 *    조회가 계속 실패하는 상황에서 어제 목록이 오늘 화면에 눌러앉는 것을 막는다.
 *  [교정3·수동 비우기] 설정 → 조회 → '캐시 비우고 다시 불러오기'. 저장 모델·상세 보강 캐시·
 *    원본 조회분·변경 감지 집합을 모두 버리고 서버에서 다시 받는다.
 *  [교정4·출처 표시] 지금 보는 목록이 캐시인지 재조회분인지 머리행·하단에 명시한다
 *    ('캐시 · 43분 전 갱신'). 갱신 시각도 캐시 write 시각이 아니라 모델 생성 시각(builtAt)을 쓴다.
 *    새로 조회했는데 캐시에 못 쓴 경우 시각이 어긋나던 문제도 함께 사라진다.
 *  [캐시] pd_cache_v35 → v36 — 저장 정책이 바뀌었고, 이미 고착된 구캐시를 한 번에 버린다.
 *  [무변경] 판별 · 라우팅 · 관리번호 교차검증 · 배타 매칭 · 정렬 · 연속 처리 · 긴급복구.
 */

/*
 * v1.25.5 (2026-08-25) — 다른 지재권의 BPM에 연결되던 오매칭 차단 (patch, 1.25.4 -> 1.25.5)
 *  [증상] 행을 눌러도 그 건이 아닌 다른 업무가 열리고, 정작 처리해야 할 건은 뜨지 않는다.
 *  [원인] 매칭 후보키(workCandidates)는 요청번호 계열뿐이고, 대괄호 토큰 일치(95점)만으로도
 *    임계값 90을 넘어 승격됐다. 요청번호 체계가 겹치거나 BPM 제목에 다른 건의 번호가 박혀 있으면
 *    엉뚱한 BPM 업무에 연결되고, 그 상태로 openResolvedMyWork가 그 BPM의 bizKey로 팝업을 연다.
 *    v1.25.4의 배타 매칭은 '한 BPM을 여러 행이 가리키는 것'만 막았을 뿐, '틀린 BPM에 붙는 것'은
 *    막지 못했다.
 *  [교정·관리번호 교차검증] BPM 행의 제목·본문·instancename에서 관리번호 형태 토큰
 *    (예 P250059US · P260088US · P260038PCT)을 뽑아 그 행의 관리번호와 대조한다.
 *    · 같은 관리번호가 있으면 +40 (확증)
 *    · 관리번호 토큰이 있는데 내 것이 없으면 -80 → 임계값 미만으로 떨어져 연결 자체가 차단된다.
 *    · BPM에 관리번호 표기가 아예 없으면 기존 점수 그대로(중립) — 과잉 차단하지 않는다.
 *    차단된 BPM 업무는 사라지지 않는다. addBpmSafetyNet이 'BPM 직접 · IPMS 미연결' 행으로
 *    올리므로, 그 행을 누르면 정확히 그 BPM 업무가 열린다.
 *  [진단] 콘솔 '[PD] BPM 연결 상세'에 행 → 나의업무 연결표(단계·관리번호·제목·BPM업무·
 *    instancename·점수)를 추가한다. 어느 행이 무엇으로 열리는지 클릭 전에 확인할 수 있다.
 *    팝업 토스트에도 instancename(bizKey)을 함께 표시한다.
 *  [수정·표시] 제목 대괄호 토큰이 관리번호와 같으면 사무소 자리에 다시 찍히던 중복을 없앤다
 *    (예 P250059US가 관리번호와 사무소 칸에 두 번 나오던 것).
 *  [무변경] 캐시 키(pd_cache_v35) · 정렬 · 라우팅 계약 · 연속 처리 · 긴급복구.
 */

/*
 * v1.25.4 (2026-08-25) — 개인저작물 후순위 · BPM 중복 승격 차단 · 행 표시 재정비 (patch, 1.25.3 -> 1.25.4)
 *  [수정1·중복 승격] 이미 처리한 건이 여러 줄로 남고, 어느 줄을 눌러도 같은 팝업(남아 있는 1건)이
 *    열리던 결함. 원인은 applyWorkflowContinuity의 매칭에 배타성이 없었던 것 — 한 BPM 업무를
 *    여러 IPMS 행이 동시에 가리킬 수 있었다. 같은 신청번호를 공유하는 패밀리(국가별 관리번호)나
 *    제목 대괄호 토큰이 겹치는 행들이 모두 '내 차례'로 승격되고 같은 myWork 팝업으로 연결됐다.
 *    · 교정: 후보를 전부 모은 뒤 BPM 건(processcode|instancename|taskid)당 최고점 1행만 승격한다.
 *      밀려난 행은 추측으로 승격하지 않고 IPMS 원 상태(baseAction·baseTrack)를 유지한다.
 *    · 진단: 밀려난 건수를 콘솔 '[PD] BPM … 중복승격 차단 N건'으로 남긴다.
 *    · 한계: 1:1 배타 매칭은 1회 통과(최고점 우선)다. 밀려난 행이 다른 BPM 건과 2순위로
 *      맞을 가능성은 계산하지 않는다 — 잘못 승격하느니 승격하지 않는 쪽을 택했다.
 *  [수정2·개인저작물 후순위] 개인저작물(tets)은 특허 처리 흐름과 축이 다른데 BPM 안전망 항목이라
 *    sort -2500을 받아 전체 목록 최상단을 차지했다. 전체에서 최후미(TETS_SORT)로 내린다.
 *    같은 단계 안에서는 경과일 순서를 유지하고, 마스터 검색 결과보다는 위에 둔다.
 *    캐시 모델에도 normalizeModelActions에서 같은 규칙을 적용해 구캐시 표시를 교정한다.
 *  [수정3·행 가독성] 단계 표기를 대괄호 [신청] → 둥근 배지로 바꾸고 최소폭(64px)을 고정해
 *    제목 시작선을 세로로 맞춘다. 메타는 같은 회색 문자열을 가운뎃점으로만 잇던 방식을 버리고
 *    종류를 가진 토큰(관리번호·주발명자·사무소·날짜·상태·내업무)으로 나눈다.
 *    · 관리번호 고정폭(mono·잉크색) / 주발명자 진회색 / 사무소·날짜 연회색 / 구분은 얇은 세로선.
 *    · 메타 폭을 max-width → width로 고정(38%, 주발명자 표시 시 50%)해 관리번호 열이 세로로 선다.
 *    · 표시 계층 한정 — 판별·정렬·라우팅·POST 계약 무변경.
 *  [무변경] 캐시 키(pd_cache_v35) · 연속 처리 창 핸들 포획 · 팝업 계약 · 키보드 내비 · 긴급복구.
 */

/*
 * v1.25.3 (2026-08-25) — 연속 처리 팝업 내용 누락 수정 · 목록 메타에 주발명자·특허사무소 (patch, 1.25.2 -> 1.25.3)
 *  [수정1·연속 처리 팝업] 연속 처리(및 설정 '팝업 연속 열기') 중에는 팝업이 떠도 해당 건 내용이 비어 있고,
 *    같은 항목을 개별 클릭하면 정상이던 결함.
 *    · 원인: v1.23.2가 닫힘 감지(창 핸들 폴링)를 위해 연속 처리 중 모든 팝업을 submitPopup(원시 숨은 폼 POST)로
 *      강제 우회했다 — callPortalPopup은 isChainMode()면 즉시 false, openResolvedMyWork·bpmFn 분기도
 *      fnShowWorkBpmPopup을 건너뛰었다. 개별 클릭은 포털 함수($.popupWindow / fnShowWorkBpmPopup→$.postWindow)로
 *      열리므로 두 경로는 서로 다른 방식으로 창을 연다. submitPopup은 (a) 샌드박스 window.open('') 빈 창을 먼저
 *      열고 폼 target=창이름으로 POST하는데, 이 빈 창이 확장 오리진으로 열려 POST가 안착하지 못하는 사례가
 *      v1.23.1(지출발의 신청)에서 이미 실측됐고, (b) $.popupWindow의 dataSource 전달 방식과의 동등성은 실측된 바
 *      없다(kriss.popup.js 내부는 지식팩 v1.0에도 없음). 즉 연속 처리 = 미검증 경로 100%, 개별 클릭 = 실측 경로.
 *    · 교정: 연속 처리 중에도 포털 경로를 그대로 쓴다. 대신 호출하는 동안만 페이지 window.open(UW.open)을 감싸
 *      반환 창 핸들을 포획(withOpenCapture)해 기존 폴링(pdWatchPops)에 올린다. 동기 포획이 없으면 1.5초 유예 후
 *      원복. 핸들을 끝내 못 얻으면(팝업 차단·핸들 미반환) 다음 건을 추측으로 열지 않고 연속 처리를 중단·안내한다.
 *    · 이중 진행 방지: 핸들이 잡힌 창의 $.popupWindow onCallback은 포커스 복귀만 하고, 다음 건 진행은 폴링이 담당.
 *  [보강·submitPopup] 남은 원시 POST 경로(신청 B_RES00004·업무요청 03/04 B_RES00012·applyReview·포털 함수 부재
 *    폴백)의 빈 창 사전 오픈을 window.open('') → UW.open('about:blank')(페이지 컨텍스트·명시 URL)로 교체.
 *    v1.23.1 실측 결함과 같은 패턴이었다. UW.open 실패 시 기존 window.open 폴백.
 *  [부수] pdWatchPops의 setInterval을 RUNTIME.interval로 등록 — 긴급복구 시 폴링이 남던 누수 정리.
 *    포획 훅은 RUNTIME.cleanups·stop()에서 원복된다(stop은 콜백 없이 silent 원복).
 *  [추가1·주발명자·사무소] 행 메타에 관리번호 다음으로 주발명자·특허사무소를 표시(설정 → 표시 →
 *    '주발명자·사무소 표시', pd_who_v1, 기본 ON). 표시 계층 한정 — 판별·정렬·라우팅 무변경.
 *    · 근거(지식팩 v1.0 그리드 사전): 신청 mainIvenEmpNm·plfNm(희망특허사무소) / 선행조사 mainIvenEmpNm·busiRegNm
 *      / 출원 plfNm(주발명자 열 없음). 등록·업무요청·청구서 목록은 다단 헤더의 상위 그룹명만 수집되어 열 미실측.
 *    · 보강: 행에 없으면 같은 관리번호·신청번호의 다른 조회분(선행조사·출원 → 청구서·등록·업무요청 → 신청)에서
 *      채운다. 추가 API 없음. 사무소는 BPM 제목 대괄호([H&P특허] 등)와 겹치면 한 번만 표시.
 *    · 진단: 콘솔 '[PD] 데이터 진단'에 단계별 채움 출처(행/보강/없음) 표 추가 — 어느 목록 API에 필드가 없는지
 *      확인해 회신하면 후보 필드명을 보강할 수 있다.
 *  [캐시] pd_cache_v34 → v35 (항목 모델에 mainIven/office/whoSrc 추가).
 *  [무변경] 판별 · 라우팅 대상 화면·POST 계약 · 바로가기 소유권 계약 · 상태 칩 · 흐름 패널.
 */

/*
 * v1.25.2 (2026-08-24) — 개인저작물(B_RES00002) 단계 신설 · '업무요청' 오분류 교정 (patch, 1.25.1 -> 1.25.2)
 *  [원인] 개인저작물 등록 건은 BPM 나의업무(processcode B_RES00002, 컨테이너 /pms/res/tets/
 *    B_RES00002_01.do — 지식팩 경로 실측, 업무명은 미확정)로만 내려오는데, 이 코드가
 *    BPM_PROCESS_META에 없어 텍스트 폴백(/지식재산|특허|…|등록|…/)에 걸렸다. '개인저작물 등록'의
 *    '등록'이 특허 등록 키워드에 오매칭되어 stage 'task'(업무요청) · '미분류 특허 BPM' 라벨로
 *    표시되던 것이 문제의 전부다.
 *  [교정1·1급 분류] B_RES00002를 BPM_PROCESS_META에 정식 등재(stage 'tets' · 라벨 '개인저작물 등록'
 *    — 명칭은 사용자 확인 기준). 이제 폴백이 아니라 코드 매핑으로 분류되며, expectedProcesses의
 *    단계↔코드 역매핑에도 자동 포함되어 나의업무 연결 정확도가 함께 오른다.
 *  [교정2·단계 노출] STAGE_NM.tets='개인저작물'. 탭은 pm과 같은 관례로 해당 건이 있을 때만
 *    stageKeys()에 합류한다(상시 탭 증설 없음). IPMS_URL.tets=S_PMS_03020305(개인저작물 관리)를
 *    등재해 KrissDash.openList('tets') 폴백이 업무요청 화면으로 새지 않게 한다. 클릭 라우팅은
 *    기존 myWork 직진입(ext2=B_RES00002_01.do) 경로 그대로다.
 *  [범위] 텍스트 폴백 정규식은 유지한다 — 미지의 특허 BPM을 놓치지 않기 위한 안전망이며,
 *    B_RES00002가 1급 매핑으로 선점되므로 이 오매칭은 재발하지 않는다.
 *  [캐시] pd_cache_v33 → v34 (구캐시에 남은 task-오분류 개인저작물 행 잔존 방지).
 *  [무변경] 바로가기 소유권 계약(KrissDash·#pt-quick·폴백 감시) · 상태 칩 · 레일 · 흐름 패널.
 */

/*
 * v1.25.1 (2026-08-24) — 폴백 바로가기 중복 제거 · 상태 칩 잠금 방지 (patch, 1.25.0 -> 1.25.1)
 *  [수정1·늦은 테마 중복] 부팅 2.6초 검사에서 테마(#pt-quick)가 없어 폴백 줄을 만든 뒤 테마가
 *    뒤늦게 그려지면 바로가기가 두 줄로 공존했다(jsdom 재현: 테마 3.2초 마운트 시 중복 확인).
 *    폴백 생성 후 2초 간격 감시를 붙여 #pt-quick 등장 즉시 폴백(#pd-go)을 걷어낸다.
 *    감시는 RUNTIME.interval로 등록되어 긴급복구(Alt+Shift+X) 시 함께 정리된다.
 *  [수정2·칩 잠금 방지] '경과/오늘 마감/신규' 칩은 0건이면 렌더되지 않는데, 칩 필터 활성 중
 *    재조회·기준선 갱신으로 해당 건수가 0이 되면 머리행에서 해제할 칩이 사라졌다
 *    (적용 배지 ✕ 또는 빈 목록의 '필터 해제'로만 해제 가능). 활성 칩은 0건이어도 유지 표시하여
 *    같은 자리 재클릭 해제를 보장한다. 판별·정렬 무관(표시 계층 한정) 원칙은 그대로다.
 *  [수정3·표기 정합] KrissDash.stages()의 pm 라벨이 STAGE_NM('연차')로 나가 폴백 버튼('연차료')과
 *    달랐고, 기존 '연차료' 폴백 표현식은 도달 불가(사문)였다. master/pm 라벨을 명시 매핑
 *    ('마스터'/'연차료')으로 교체해 테마 렌더와 폴백 렌더의 표기를 일치시킨다.
 *  [확인·기록] 접힘(collapsed) 상태에서는 폴백이 pd-body 내부에 있어 보이지 않는다
 *    (v1.23.3의 패널 최상단 상시 노출과 다른 동작). 폴백은 '테마 부재 시 기능 상실 방지'가
 *    목적이고 펼치면 즉시 접근 가능하므로 위치는 유지하되 동작 차이를 기록해 둔다.
 *  [무변경] 대상 화면·POST 계약 · 판별 · 라우팅 · 캐시(pd_cache_v33) · 키보드 내비 · 긴급복구.
 */

/*
 * v1.25.0 (2026-08-23) — 바로가기 소유권 이관 · 시안 v3 표시 계층 반영 (minor revision, 1.23.3 -> 1.25.0)
 *  [이관·바로가기] 패널 상단 '바로가기' 줄을 제거하고, 포털 검색창(#search_box) 옆 바로가기는
 *    [KRISS Portal] 메인 화면 테마 v1.5.0(#pt-quick)이 소유한다. 대시보드는 진입 계약만
 *    unsafeWindow.KrissDash로 공개한다(openList·openExpProposal·openTets·openConsole·refresh·stages).
 *    · 근거: 화면 이동은 포털 전역 내비게이션의 일이고, 대시보드는 '오늘 처리할 업무'의 현황판이다.
 *      두 스크립트가 같은 줄을 그리면 위계가 흐려지고 잉크가 중복된다.
 *    · 안전망: 테마가 바를 그리지 못한 환경(테마 미설치·검색창 부재)에서는 부팅 2.6초 후
 *      패널 하단에 기존 바로가기 줄을 폴백으로 만든다. 대상 화면·POST 계약은 무변경.
 *  [이관·포털 레이아웃] 위젯 표시/숨김·순서는 테마의 '위젯 정리'가 담당한다(v1.23.3 분리의 완결).
 *    이 파일에는 과거 잔재(data-pd-w/oidx)를 되돌리는 복구 경로만 남긴다.
 *  [시안1·머리행 신호] '경과 N · 신규 N' 텍스트를 클릭 가능한 상태 칩 3종으로 교체
 *    (경과 / 오늘 마감 / 신규). 칩 클릭 = 그 조건만 보기, 재클릭 = 해제. 표시 계층 필터이며
 *    판별·정렬에는 관여하지 않는다. urgFilter에 today·new 추가.
 *  [시안2·행 긴급도] 행 좌측 3px 색 레일(경과 적색·임박 황색)을 추가하고, 흐름 패널이 열린
 *    관리번호의 행은 선택 상태(옅은 주황 배경·1px 주황 테두리)로 표시한다. 행은 한 줄 유지.
 *  [시안3·트랙 토글] 밑줄 → 세그먼트 필(활성 = 흰 카드). 단계 필터 카운트 pill은 유지.
 *  [시안4·흐름 패널] 제목 '선택 업무 흐름', 완료 단계는 체크 원형·현재 단계는 주황 링·
 *    미도달은 빈 원. 관리번호 14.5px, 청구서 축은 카드로 분리. 없는 단계는 '대기'로 표기.
 *  [시안5·갱신 시각] 머리행 우측에 '마지막 갱신 N분 전'을 노출(하단은 조회기간·표시건수,
 *    머리행은 신선도 — 역할이 다르다). 종합 콘솔은 검은 필 → 조용한 외곽선.
 *  [유지] 연속 처리 버튼(현행 디자인·동작 그대로) · 목록 1행 입력 · 키보드 내비 · 판별 · 라우팅 ·
 *    캐시(pd_cache_v33) · 긴급복구.
 */

/*
 * v1.23.3 (2026-08-21) — 안정화 우선 패치 · 포털 레이아웃/통계 책임 분리 (patch, 1.23.2 -> 1.23.3)
 *  [분리1·디자인 책임] 대시보드는 #pd-panel 내부의 기능 UI만 소유한다. 포털 위젯 이동·개별 크기·순서·
 *    상단 여백 편집은 제거하고 메인 화면 테마에 맡긴다. 포털의 2열 float/절대배치 구조를 대시보드가
 *    transform·height로 다시 건드리지 않아 테마와의 충돌 및 우측 잘림·짝 어긋남을 방지한다.
 *  [분리2·통계] 통계 내보내기·기간별 통계 UI/코드를 제거한다. 별도 KRISS Patent Stats Extractor가
 *    통계·보고서 역할을 담당하며, 대시보드는 오늘의 처리 업무와 진행 추적에만 집중한다.
 *  [안정1·캐시 우선] 캐시를 BPM 조회보다 먼저 즉시 렌더하고, 최신 조회만 화면을 교체하도록 load 세대번호와
 *    AbortController를 도입했다. 연속 새로고침 시 늦게 끝난 구 요청이 새 결과를 덮지 않는다.
 *  [안정2·부분실패 보존] 6개 핵심 IPMS 소스 중 하나라도 실패·스키마 불일치·부분수신이면 정상 캐시를
 *    덮어쓰지 않는다. 캐시가 없을 때만 부분 결과를 경고와 함께 임시 표시한다.
 *  [누락방지·BPM 안전망] 현재 나의업무와 IPMS 행이 연결되지 않아도, 확정된 특허 BPM(B_RES00004/11/12/15/16)은
 *    'BPM 직접 · IPMS 미연결' 항목으로 표시한다. 특히 특허 연차유지여부(B_RES00016)를 현재업무 안전망에 포함.
 *  [안정3·수신무결성] 청구서/마스터 300건 상한도 total까지 재조회하고, 6000건 초과·total 불명 300건은
 *    부분수신으로 경고한다. 응답 자동탐색 배열은 소스별 핵심 필드 검증을 통과해야만 사용한다.
 *  [정합] 상태코드 2자리 정규화, 월말 기준 조회기간 계산, PCT 포함 관리번호 접미 2~4자 인식.
 *    청구서 완료(11)와 선행조사 임시저장(00)의 진행중 잡음도 제외한다.
 *  [생명주기] 긴급복구 시 진행 요청·타이머·interval·document 이벤트·팝업 감시를 모두 정리한다.
 *  [안전] 선행조사 생성 중복 클릭 잠금 및 생성 직후 강제 갱신. node --check 및 정적 회귀검사 통과.
 */

/*
 * v1.23.2 (2026-08-21) — 시안 v3 반영: 우측 흐름 패널 · GNB 재구성 · 연속 처리 수정 (patch, 1.23.1 -> 1.23.2)
 *  [수정1·GNB 위계] 바로가기 줄을 패널 최상단(머리행 위)으로 — 화면 이동이 상위 내비게이션.
 *    트랙 토글(처리할 업무/진행중)은 기존 밑줄 스타일 유지(사용자 확인).
 *  [수정2·연속 처리 동작] 시작해도 다음 건이 안 열리던 원인: $.popupWindow 경로는 onCallback이
 *    팝업의 명시적 콜백에서만 발화 — 손으로 닫으면 감지 불가. → 연속 처리 중에는 창 핸들 폴링이
 *    가능한 submitPopup 경로를 강제(callPortalPopup·fnShowWorkBpmPopup 우회). 평상시 라우팅 무변경.
 *  [변경1·흐름 패널] 관리번호 클릭 흐름을 행 아래 인라인 → 목록 우측 사이드 패널(300px)로 이동.
 *    세로 타임라인(신청→선행조사→출원→등록, 상태명·일자) + 청구서 건별 건수. ✕ 또는 Esc로 닫기.
 *    RAW 조회분 재사용(추가 API 없음)은 동일.
 *  [변경2·GNB] 트랙 토글(처리할 업무/진행중)을 밑줄 → 세그먼트 필(활성=흰 카드)로.
 *  [변경3·필터] 단계 필터를 텍스트 → 카운트 pill(활성=주황 배경 #FDEADD)로. 0건은 흐린 회색 유지.
 *  [변경4·바로가기] 필터와 시각 충돌 해소 — 회색 소형 텍스트 링크(호버 시 주황 밑줄)로 강등.
 *  [유지] 키보드 내비(↑↓/Enter/Home/End)·연속 처리(Esc 중지)·판별·라우팅·캐시(pd_cache_v32) 무변경.
 *  [예정] '특허 흐름'(관리번호별 전체 표)·'통계' 상단 탭은 v1.25에서 — 시안 v3 확정 구조.
 */

/*
 * v1.23.1 (2026-08-21) — 실사용 결함 3건 수정 (patch, 1.23.0 -> 1.23.1)
 *  [수정1·지출발의 신청 오동작] 클릭 시 확장 프로그램 페이지로 새던 문제. 원인: 사전
 *    window.open('') 빈 창이 샌드박스 컨텍스트에서 확장 오리진으로 열림. → 빈 창 사전 오픈을
 *    없애고 폼 target=_blank 직접 제출로 교체(POST 계약 bizKey 빈값 포함 동일). 사용자 클릭
 *    제스처 안에서 제출되므로 팝업 차단도 회피.
 *  [수정2·신청일자 표시] 시간레일의 경과(+N)·D-day만으로는 날짜가 안 보임 → 메타에 기준일자
 *    (MM.DD) 복원 표시. elapsed·dv는 원 날짜에서 계산된 값이라 역산이 정확하다. 날짜 신호가
 *    아예 없는 행은 표시하지 않음(데이터 부재).
 *  [수정3·파이프라인 점 제거] 단계는 제목 앞 [출원]·[신청] 태그로 이미 표시 → 4점 아이콘은
 *    중복 잉크라 제거(관리번호 클릭 흐름은 유지). 대신 정보 가시성 보강:
 *    · 메타 중복 제거 — [신청] 태그와 같은 상태명('신청')은 생략, 내업무 상태명도 중복 시 생략.
 *    · 관리번호를 잉크색·500 굵기로 올려 상태(회색)와 시각 계층 분리.
 *  [캐시] 불변(pd_cache_v32 유지 — 표시 계층만 변경).
 */

/*
 * v1.23.0 (2026-08-21) — 목록 파이프라인·관리번호 흐름·연속 처리 버튼·바로가기 확장 (minor revision, 1.22.1 -> 1.23.0)
 *  [추가1·미니 파이프라인] 각 행 시간레일 옆 4점(신청→선행조사→출원→등록)으로 현재 단계 표시.
 *    청구서·업무요청은 단계가 아니라 건별로 발생하는 별도 축이므로 점을 찍지 않는다(빈 자리로 정렬 유지).
 *  [추가2·관리번호 흐름] 행 메타의 관리번호 클릭 → 그 지재권의 단계 흐름(단계별 상태명·최근일)과
 *    청구서 진행/누적 건수를 행 바로 아래 인라인으로 표시. RAW 조회분 재사용 — 추가 API 없음.
 *    재클릭=닫기, 다른 번호 클릭=전환. 캐시만 있고 RAW가 없으면 새로고침 안내.
 *  [추가3·연속 처리 버튼] 하단 바 '연속 처리' — 첫 항목부터 팝업을 열고 닫히면 다음 건 자동 오픈.
 *    v1.22.0 '팝업 연속 열기'(설정·영구)의 세션 한정 승격판(저장 안 함). Esc 또는 재클릭으로 중지.
 *    자동 오픈은 사용자 제스처가 아니므로 krisstar 팝업 허용 필요(기존 제약 동일).
 *  [추가4·바로가기 확장] 개인저작물(S_PMS_03020305 새 창) + 지출발의 신청(S_ACC_01020100 POST —
 *    bizKey:'' · workFlag:newWork · processCode:B_ACT00002 · statusCode:ST0100 · subFlag:N,
 *    [연차유지료] 스크립트 실측 계약). 빈 bizKey도 전송해야 하므로 submitPopup(빈값 생략) 대신 전용 폼 POST.
 *  [추가5·종합 콘솔] 머리행 '종합 콘솔 ↗' — 요구자료 콘솔(S_COM_00000000P) 새 창. 대시보드는 현황판,
 *    심화 작업(요구자료 추출 등)은 콘솔 담당(A/B안 결정 전까지 진입점만 제공).
 *  [제거·검색창] 패널 검색창·'/' 단축키 제거 — [특허] 팔레트(Ctrl+Space)가 검색·이동 담당.
 *    runMasterSearch 등 마스터 검색 코드는 보존(팔레트·후속 연계용).
 *  [디자인] 팔레트를 메인 테마 v1.4.0 톤으로 통일(중립 #17181C/#5F6470/#9AA0AC · 라인 #E7E8EC/#DCDDE3 ·
 *    accent #C14E08/#FDEADD). 바로가기는 박스 칩 → 조용한 텍스트 버튼(호버 옅은 배경).
 *  [캐시] pd_cache_v31 → v32. [안전] 쓰기 흐름 무변경(지출발의 신청 창 열기는 포털 신규작성 진입과 동일).
 */

/*
 * v1.22.1 (2026-08-19) — 국외 신청 제외 강화 · 미제출 판정을 Helper 원장으로 이관 (patch, 1.22.0 -> 1.22.1)
 *  [수정1·국외 제외] 신청완료(04) 건의 국가 판정을 판별부 최상단으로 올려, 선행조사 관련 액션
 *    전체(요청·확인·미제출)에 일괄 적용. 국외·PCT는 목록에 아예 오르지 않는다.
 *    · v1.22.0 결함: 관리번호 접미 판정에 MNG_RE(끝 2글자)를 써서 3글자 접미인 PCT 건
 *      (예 P260038PCT)이 'UNKNOWN'으로 빠져 '확인' 라벨로 계속 노출됐다.
 *      → 접미 2~4글자를 읽어 KR 외에는 전부 국외로 판정하도록 교체.
 *    · 판정 순서: cntCls(I/O/M) → 국가명(cntClsNm·aplyNtnNm) → 관리번호 접미(P260084US→US).
 *      국가명 키워드에 주요 출원국(미국·일본·유럽·중국·싱가포르 등) 추가.
 *    · 진단: 제외 건수는 콘솔 게이트 로그에 '국외제외'로 집계된다.
 *  [수정2·미제출 판정 이관] v1.22.0의 추정 판정(선행조사 목록 임시저장 대조·30일 유예)을 제거하고,
 *    입력 Helper v1.8.6 이상이 기록하는 원장(localStorage 'kriss.pps.draft.v1')만 근거로 사용.
 *    · Helper는 선행조사 팝업의 결재상태를 직접 읽으므로 목록 API 반환 여부와 무관하게 정확하다.
 *    · 원장에 draft로 기록된 건만 '선행조사 작성 필요 (미제출)'로 표시. 원장이 없으면(=Helper
 *      미설치·미방문) 아무 것도 표시하지 않아 오탐이 생기지 않는다.
 *    · PPS_IDX의 임시저장 집계(draft)와 '목록 미확인' 경로는 함께 삭제.
 *  [무변경] 라우팅·팝업 계약·키보드 내비·포커스 복귀·팝업 연속 열기.
 *  [캐시] pd_cache_v30 → v31 (구캐시의 국외·확인 항목 잔존 방지).
 */

/*
 * v1.22.0 (2026-08-19) — 선행조사 KR 한정·임시저장 추적 + 키보드 내비·팝업 연속 열기 (minor revision, 1.21.0 -> 1.22.0)
 *  [수정1·선행조사 KR 한정] '신청완료 → 선행조사 요청'은 국내(KR) 출원 신청에만 표시.
 *    · 판정 신호(우선순위): 목록 cntCls(I=국내/O=국외/M=PCT) → cntClsNm → 관리번호 접미
 *      2글자(MNG_RE, 예 P260075KR) → 상세(searchIntellRqst) 보강값(cntCls·cntClsNm).
 *    · 국외·PCT → 제안 자체를 제외. 신호 전무(UNKNOWN) → 생성 대신 '확인(국가 미확인)'으로
 *      강등(applyReview 조회만) — 잘못된 선행조사 생성 방지 우선.
 *    · 보류(차기): KR 예외(타기관 주관 등) — 분할(D)은 기존 reRqstType=G 한정으로 이미 제외.
 *      타기관 주관 판정 필드는 미실측이라 이번 범위 제외.
 *  [수정2·임시저장 추적] 생성 클릭만으로 '선행조사 했음'으로 인식되던 문제 해소.
 *    · PPS_IDX에 임시저장(apvStat 00) 건수(draft) 추가 집계.
 *    · ppsRqstNo가 있어도 대조 결과가 전부 임시저장이면 '선행조사 작성 필요(임시저장 미제출)'
 *      액션으로 처리목록에 유지(routeKind ppsDraft — 생성 없이 기존 번호로 입력창만 오픈).
 *    · 대조 미포함(생성 직후 목록 미반영 등: 요청일 없음 또는 30일 이내)은 '상태 확인'으로 표시.
 *    · 생성 확인문구에 '저장·제출까지 완료해야 실제 신청됩니다' 명시.
 *    · ⚠️ 선행조사 목록 API가 임시저장(00) 행을 반환하는지 미실측 — 미반환 시 '목록 미확인'
 *      경로로만 잡힘. F12 확인 권장.
 *  [추가1·키보드 내비] 목록 ↑/↓ 이동, Enter/Space 열기, Home/End(기존 Enter 확장).
 *    재렌더 후 커서 위치 복원(focusPending).
 *  [추가2·포커스 복귀] 대시보드가 연 팝업이 닫히면 창 포커스 복귀 시도 + 직전 행 커서 복원.
 *    submitPopup 창=핸들 폴링, $.popupWindow=onCallback 감지.
 *    ⚠️ fnShowWorkBpmPopup(myWork) 창은 핸들 미보유로 감지 불가(브라우저 기본 동작).
 *    ⚠️ window.focus()는 브라우저 정책상 무시될 수 있음 — 이 경우 커서 복원만 동작.
 *  [추가3·팝업 연속 열기(옵션)] 설정 → 표시 → '팝업 연속 열기'(pd_chain_v1, 기본 OFF).
 *    팝업이 닫히면 다음 항목 팝업 자동 오픈(포털/마스터 행 건너뜀).
 *    ⚠️ 자동 오픈은 사용자 제스처가 아니어서 팝업 차단 대상 — krisstar 팝업 허용 필요.
 *  [캐시] pd_cache_v29 → v30 (신규 라벨·라우트 반영, 구캐시 오라우팅 방지).
 *  [안전] 쓰기 흐름 무변경(선행조사 생성은 기존과 동일하게 명시적 확인 후에만). node --check 통과.
 */

/*
 * v1.21.0 (2026-08-18) — 업무 연속성: IPMS ↔ 나의업무 BPM 연결 + 신청→선행조사→출원지시
 *  [핵심1·나의업무 resolver] /selectMyWork.json을 대시보드 표시옵션과 무관하게 내부 조회.
 *    IPMS 행의 bpmRqstNo·cnfRqstNo·stageRqstNo·intellRqstNo 등과 BPM instancename을 대조해
 *    processCode·statusCode·ext2를 확보. 매칭된 행은 progress 상태라도 즉시 '처리할 업무'로 승격하고
 *    클릭 시 포털 공식 fnShowWorkBpmPopup(..., workFlag:'myWork') 계약으로 연다.
 *  [핵심2·업무요청] B_RES00012가 내 업무로 돌아오면 진행중에서 처리대상으로 승격.
 *    ST0103은 실제 화면 규칙상 특허사무소 전달사항(mssage)이 필수이므로
 *    '박사 검토완료 → 특허사무소 전달'로 표시한다.
 *  [핵심3·청구서] B_RES00015(cnfRqstNo)가 나의업무에 있으면 청구서 목록 상태가 검토중이어도
 *    '청구서 검토 · 내 차례'로 승격하고 정확한 myWork 팝업으로 직진입한다.
 *  [핵심4·신청→선행조사] 신청완료(apvStat=04) + ppsRqstNo 없음 건은 상세
 *    searchIntellRqst.json에서 reRqstType을 확인. 일반출원(G)만 '신청완료 → 선행조사 요청'으로 표시.
 *    클릭 시 원본 #btnPpsRqst와 동일한 updateIntellPpsInfo.json 흐름을 사용자 확인 후 실행하고 팝업을 연다.
 *  [핵심5·선행조사→출원지시] 선행조사 완료(apvStat=04)가 신청행/선행조사 목록 대조로 확인되면
 *    기존 14일 경과 조건을 제거하고 즉시 '선행조사 완료 → 출원지시·메일'로 표시.
 *    클릭 시 S_PMS_03012020을 intellRqstNo로 열며, 원 화면 출원지시는 email* 필드를 포함해 처리한다.
 *  [안전] 선행조사 생성만 명시적 사용자 확인 후 쓰기. 나머지 resolver·조회·팝업 연결은 조회/열기 전용.
 *  [캐시] pd_cache_v28 → v29(연속성 메타 baseAction/baseTrack 및 routeKind 반영).
 */

/*
 * v1.20.2 (2026-07-30) — 단계 태그·구획 폐지·변경 감지·하단 고정·위젯 높이 (patch, 1.20.1 -> 1.20.2)
 *  [수정1·단계 태그] 제목 앞에 [업무요청]·[출원]·[등록] 등 단계를 대괄호로 표기. 메타에서 단계를
 *    빼고 관리번호·상태·사무소만 남겨 중복 제거. 포털·마스터 행도 [포털]·[마스터]로 동일 규칙.
 *  [수정2·구획 폐지] '기한 경과 / 이번 주 / 이후 기한 / 기한 없음' 구획 헤더 제거. 구분이 실무상
 *    무의미하다는 판단에 따라 단일 목록으로 통합하고 정렬(급한 순)만 유지. 긴급도는 시간 레일 색으로만
 *    표시. 구획 헤더가 사라진 만큼 같은 높이에서 노출 행수가 늘어난다.
 *  [보완] 구획 제거로 잃는 '경과 건수'는 머리행 요약(경과 N · 신규 N)으로 대체.
 *  [수정3·변경 감지] 하루 첫 조회 시점의 상태를 기준선으로 저장하고(저장키 pd_seen_v1), 이후
 *    새로 생긴 건은 NEW, 상태가 바뀐 건은 표시를 붙인다. 추가 API 없이 기존 조회 결과만 사용.
 *    기준선은 날짜가 바뀔 때만 갱신하므로 하루 동안 '어제 대비'가 유지된다. 최초 실행은 기준선만 저장.
 *  [수정4·하단 고정] 하단 바를 sticky로 고정해 목록이 길어져도 화면 아래에 남게 함. 조회 정보와
 *    높이 버튼이 붙어 보이던 간격 문제도 구분자·여백으로 정리.
 *  [수정5·위젯 높이] 포털 레이아웃 관리에 높이 조절 추가(−/+ 60px, 직접 입력, 자동 복귀).
 *    드래그 핸들보다 정확하고 조작이 쉽다. 폭은 포털 3컬럼 구조에 종속되므로 제공하지 않는다.
 *  [무변경] 데이터 판별·팝업 라우팅·API·캐시·모달 골격·킬스위치.
 */

/*
 * v1.20.1 (2026-07-30) — 포털 업무 분리 · 포털 레이아웃 관리 · 바로가기 상단 박스 (patch, 1.20.0 -> 1.20.1)
 *  [수정1·포털 업무] 포털 '나의 업무'(#myWork)는 같은 화면 아래 위젯에 이미 있으므로 대시보드에서
 *    기본 제외. 설정 → 표시 → '포털 업무 포함' 체크 시 예전처럼 병합(저장키 pd_portal_v1, 기본 false).
 *    제외 시 트랙 카운트·필터·구획에서 함께 빠지며, 포털 필터 항목 자체를 감춘다.
 *    (진행중 트랙의 #myWorkIng도 동일 규칙. 파싱 로직·DOM 위임 클릭은 그대로 유지)
 *  [수정2·포털 레이아웃] 편집모드(드래그/리사이즈)만으로는 실제 배치 조정이 어려워 관리 화면 신설.
 *    설정 → 표시 → '포털 레이아웃'. 좌·중·우 3개 컬럼의 위젯을 자동 스캔해
 *    ① 표시/숨김 체크 ② 컬럼 내 순서 위·아래 이동을 제공(저장키 pd_wl_v1).
 *    · 대상 확장: 기존 6개 하드코딩 셀렉터 → #con_left·#con_center·#con_right의 .widget 전수 스캔.
 *    · 순서는 DOM 이동(노드 유지)으로만 처리하고 원래 인덱스를 data-pd-oidx에 보존 → 원복 가능.
 *    · 긴급복구(Alt+Shift+X)와 '위젯 레이아웃 초기화'에서 숨김·순서까지 함께 되돌린다.
 *  [수정3·바로가기] 하단 바 → 머리행 아래 전용 줄로 이동하고 텍스트 링크를 박스 칩으로 교체
 *    (흰 배경·1px 테두리·radius 8·12.5px, hover 시 accent). 클릭 영역이 넓어지고 가독성 향상.
 *    하단 바에는 조회 정보와 목록 높이만 남는다.
 *  [무변경] 데이터 판별·팝업 라우팅·API·캐시·목록 구조·모달 2종·킬스위치.
 */

/*
 * v1.20.0 (2026-07-30) — 표시 계층 전면 재설계: 일일 브리핑 시트 (minor revision, 1.19.2 -> 1.20.0)
 *  [배경] v1.19.0~1.19.2의 표(스프레드시트) 접근을 폐기. 데이터가 희소·이질적이라 모든 행이
 *    같은 필드를 갖지 않는데 고정 열을 강제해, 빈 열·거대한 공백·기준선 이중화가 발생했다.
 *    v1.19.2 실캡처 확인 결함: ① 포털 행 열병합이 좌측 기준선을 둘로 나눔 ② 상태 열 우측 200px 공백
 *    ③ 앞머리 쉼표·꼬리 토큰('기타·O')·사무소 대괄호가 제목에 노출 ④ 필터 8 + 바로가기 8이 한 줄.
 *  [설계 원칙] 표가 아니라 '시간 레일 + 제목 + 메타' 3부 구조의 목록. 값이 없으면 조각만 사라지고
 *    기준선은 하나로 유지된다. 계층은 크기·굵기·여백으로만 만들고, 색은 긴급도 한 역할에만 쓴다.
 *  [타입] 4단만 사용: 20 / 13.5 / 12.5 / 11.5px, 굵기 400·500·650. 기존 7단(10.5~13.5)의
 *    촘촘한 스케일이 계층 대신 잡음을 만들었다. 숫자는 전역 tabular.
 *  [색] 중립을 브랜드 색조(주황)로 온톤 처리(warm neutral). accent(#B85C1E)는 상호작용·활성 전용,
 *    긴급도는 경과(#B3392E)·임박(#9A6B0F) 두 색으로 시간 레일과 구획 라벨에만. 상태 배지 없음.
 *  [행] 시간 레일 52px 우측 정렬(레일이 스캔의 축) · 제목 13.5px/500 + 발명명칭 12.5px 회색 이어붙임
 *    · 메타(단계 · 관리번호 · 상태) 우측. 행 높이 약 30px. hover 시 우측 ↗ 노출.
 *  [구획] 배경·테두리 없이 여백 리듬으로 분리(위 16px / 아래 6px), 라벨은 긴급도 색. sticky 유지.
 *  [텍스트 위생] cleanText: 앞뒤 구분자·쉼표 제거, 대괄호(사무소·문서번호) 분리 후 메타로 이동,
 *    꼬리 잡토큰(기타·단문자) 제거, 중복 구분자 축약, 관리번호 중복 제거. 원본 데이터 불변.
 *  [크롬] 2줄 + 하단 바. 머리행(제목·큰 카운트·날짜 / 트랙·검색·도구), 필터행(단계·적용중 칩),
 *    하단 바(바로가기 8 · 조회 정보 · 목록 높이). 바로가기를 필터 줄에서 하단으로 이동해 경쟁 제거.
 *  [밀도] 목록 기본 높이 560px, 3단(560 / 860 / 전체). 같은 폭에서 약 16행 노출.
 *  [무변경] 데이터 판별·팝업 라우팅·API·캐시(pd_cache_v28)·저장키·모달·편집모드·킬스위치.
 *    v1.19.2는 폴백으로 보존.
 */

/*
 * v1.19.2 (2026-07-30) — 실측 렌더 기준 표시 재조정 (patch, 1.19.1 -> 1.19.2)
 *  [근거] v1.19.1 실화면 캡처. 목업은 열이 고르게 채워진 가정이었으나 실제 분포가 달랐음:
 *    포털 업무 6행이 기한·단계·관리번호에 '–'·'포털'·'나의 업무'를 반복(정보량 0인 열이 좌측
 *    200px 점유) → 제목이 화면 중앙에서 시작하고 상태는 우측 끝에 고립, 사이에 큰 공백.
 *    행 높이 42px + 크롬 3줄로 16건 중 7건만 노출.
 *  [수정1·행 병합] 포털 행은 제목 셀이 1~4열을 병합(grid-column:1/5) — 반복 값 제거, 좌측 정렬 복구.
 *    마스터 행은 기한·단계를 비우고 관리번호부터 표시. 값이 없는 칸에 '–'를 찍지 않음.
 *  [수정2·공백 제거] 발명명칭 열 상한 620px + 우측 여유 열 신설. 상태가 명칭 바로 뒤에 붙고
 *    모든 행에서 같은 x에 정렬. 기존엔 1fr이 남는 폭을 모두 흡수해 상태가 멀리 밀렸음.
 *  [수정3·밀도] 행 여백 10→6px, 행간 1.45, 열 헤더 4px. 목록 기본 높이 392→520px(3단 520/780/전체).
 *    같은 폭에서 노출 행수 약 1.6배.
 *  [수정4·크롬 2줄] 검색을 머리행 우측으로 이동, 바로가기 줄 폐지 → 필터 줄 우측에 배치(상시 노출 유지).
 *  [수정5·반복 문자열] 표시 계층에서 중복 제거: 제목의 '[번호]'·담당자 접미를 보조 회색으로 분리,
 *    부제에서 관리번호 중복 제거(관리번호는 전용 열에 있음). 데이터는 변경하지 않음(표시만).
 *  [수정6·구획 순서] 기한 경과 → 이번 주 → 포털 업무 → 이후 기한 → 기한 없음. 급한 것이 최상단.
 *  [수정7·타이포] 제목 18px, 열 헤더 10.5px, 카운트는 mono 해제(sans+tnum) — mono 남용 축소.
 *    기한·관리번호만 mono 유지. 트랙 활성 밑줄·카운트에 accent 부여(무채색 일변도 완화).
 *  [무변경] 데이터 판별·팝업 라우팅·API·캐시·저장키·모달·편집모드·킬스위치.
 */

/*
 * v1.19.1 (2026-07-30) — 바로가기 상시 노출 + 표시 정제 (patch, 1.19.0 -> 1.19.1)
 *  [수정1·요청] 단계 바로가기를 메뉴에서 화면으로 되돌림. 머리행 아래 전용 줄(.pd-nav)에
 *    텍스트 링크 8개(신청·선행조사·출원·업무요청·등록·청구서·마스터·연차) 상시 표시.
 *    v1.19.0의 '↗ 화면 열기' 드롭다운(#pd-go 메뉴)·토글 분기 제거. 대상 화면·동작 동일.
 *  [구조] 크롬 3줄 고정: (1) 제목·트랙·도구 (2) 바로가기·검색 (3) 단계 필터·적용 중 칩.
 *    적용 중 칩이 전용 줄에서 필터 줄 우측으로 이동 — 필터 상태를 한 줄에서 읽고 해제.
 *  [정제1] 열 헤더를 구획마다 반복 출력하던 것을 목록 최상단 1회로 축약(반복 잉크 제거).
 *  [정제2] 열 헤더·구획 헤더 스크롤 고정(sticky). 스크롤 중 어느 구획인지 유지.
 *  [정제3] 상태 점은 경과·임박에만 표시(중립 회색 점 제거) — 색이 있는 것만 신호로 남김.
 *  [정제4] 기한 열 우측 정렬(D+21·+32일 자릿수 정렬로 세로 스캔 개선). 행 여백 9→10px,
 *    구획 상단 여백 확대(단조로운 등간격 제거).
 *  [정제5] 마스터 검색 배너를 목록 끝이 아니라 '마스터 결과' 구획 머리로 이동.
 *  [정제6] 빈 목록 안내에 '필터 해제' 링크 추가(필터가 걸린 경우에만).
 *  [추가] '/' 키로 검색창 포커스(입력 중일 때는 무동작).
 *  [무변경] 데이터 판별·팝업 라우팅·API·캐시(pd_cache_v28)·저장키·모달·편집모드·킬스위치.
 */

/*
 * v1.19.0 (2026-07-30) — 대시보드 전면 리디자인: 전폭 1컬럼·열 정렬 목록 (minor revision, 1.18.2 -> 1.19.0)
 *  [범위] 표시 계층만 교체. 데이터 판별(buildActions)·팝업 라우팅(resolvePopup/openAction)·API 계약 무변경.
 *    캐시 포맷 동일(pd_cache_v28 유지). 조회 전용·긴급복구·data-pd 규약 유지.
 *  [제거1] 보조 영역(#pd-side-placeholder)과 2컬럼 그리드(.cols) 삭제 → 목록이 패널 전폭 사용.
 *  [제거2] 중첩 카드 해제: 패널만 테두리를 갖고 내부는 헤어라인으로 구획(.card/.card-h 폐지).
 *  [제거3] 죽은 코드: renderPay()·payShown·CONF.PAY_PAGE/PAY_MAX_PX 및 .pay- · .prow · .pd-more CSS.
 *    (연차료 카드는 v1.15.1에서 이미 미호출 상태였음)
 *  [제거4] 배지·태그·칩 남용 정리: D-day 박스(.dd 테두리)·단계 태그(.tag)·빠른이동 8버튼(.pd-quick)
 *    → 열 정렬과 텍스트 필터로 대체. 빠른이동은 머리행 '↗ 화면 열기' 메뉴로 이동(항목 동일).
 *  [신규1] 목록 5열 구조: 기한 / 단계 / 관리번호 / 발명명칭·업무 / 상태(점+텍스트). 관리번호가
 *    독립 열이 되어 세로 스캔 가능(기존엔 부제 문자열에 섞여 있었음).
 *  [신규2] 시간 구획: 포털 업무 / 기한 경과 / 이번 주 / 이후 기한 / 기한 없음(경과순) / 마스터 결과.
 *    정렬은 기존 a.sort 값을 그대로 사용하고 구획만 a.dv로 계산 — 판별·정렬 로직 무변경.
 *  [신규3] 상태 열 표시명: STAT_DISP(표시 전용 사전) + 동작 라벨 단축(괄호부·단계명 제거).
 *    ⚠ 표시 전용이며 판별에는 사용하지 않음(등록 드롭다운/행실측 상충 건은 행실측 표기 유지).
 *  [신규4] 적용 중 필터 칩 + '모두 해제'. 기존엔 트랙·단계·상태·검색 4층 상태가 흩어져 있었음.
 *  [신규5] 하단 상태줄: 조회 기간·갱신 경과·표시 건수 + 목록 높이 3단(보통 392 / 크게 640 / 전체).
 *    높이는 기존에 편집모드(Alt+Shift+E) 진입이 필요했음. 저장키 pd_listh_v1 추가.
 *  [신규6] 검색창에 모드 표기(입력=수집분 필터, Enter=마스터 검색). 동작 무변경.
 *  [타이포·색] 4단 스케일(17/13.5/12.5/11)로 압축, 숫자 고정폭 유지. accent 채도 하향
 *    (#E5661C → #C9601F) 후 링크·활성 표시로 용도 제한. 상태색은 경과(red)·임박(amber) 2개만.
 *  [유지] 트랙 토글(#pd-track .tt) DOM 계약·검색 입력(#pd-q)·항목 클릭 위임(.item[data-i])·
 *    숨김 ✕(.pd-hide)·마스터 배너(.pd-mrow)·모달 2종·편집모드·킬스위치 그대로.
 *  [미확정] #con_center 실폭에 따른 열 폭 적정성(발명명칭 열 320px 미만이면 2행형 전환 검토).
 */

/*
 * v1.18.2 (2026-07-30) — '출원지시 대기' 오탐 제거: 선행조사 완료 게이트 (patch, 1.18.1 -> 1.18.2)
 *  [문제] 신청목록발 '출원지시 대기'가 선행조사 '요청일 존재(ppsRqstDt)'만으로 action에 올라와,
 *    선행조사가 아직 완료되지 않은 건(출원 단계 기준 apvStat 10 출원지시전)까지 처리할 업무로 표시.
 *    출원지시는 선행조사 완료가 선행조건이므로 업무 규칙 위반. (출원 목록발 10은 v1.17.1에서 이미 제외 →
 *    해당 성격 항목의 유입 경로는 이 push가 유일)
 *  [수정] ppsGate() 신설 — 선행조사 완료가 확인된 건만 '출원지시 대기(action)'로 push.
 *    1순위: 신청행 자체 완료 신호(ppsCmplDt/ppsEndDt, ppsApvStat) — 응답에 있으면 자동 적용, 없으면 무시.
 *    2순위: 동일 조회분 선행조사 목록(pps)을 intellRqstNo·intellMngNo로 대조, apvStat 04(완료) 확인.
 *           CONF.PPS_DONE_STRICT=true면 '미완료 잔존 시 제외'(보수), false면 '완료 1건 이상이면 통과'.
 *    3순위(판정불가): pps 조회 실패 또는 신청↔선행조사 키 불일치(linked=false) → 기존 동작 유지(누락 방지).
 *  [영향] 제외된 건은 선행조사(pps) 단계 '선행조사 진행·회신 대기 (재촉)'(progress)에 이미 표시되므로
 *    가시성 손실 없음. 사유별 건수는 콘솔 진단 '[PD] 출원지시 대기 게이트'로 확인.
 *  [라벨] '출원지시 대기 (선행조사 후 경과)' → '출원지시 대기 (선행조사 완료·경과)'.
 *    ⚠ 구 라벨을 '표시 제외'에 넣어둔 경우 제외가 풀림 → 필요 시 재설정.
 *  [근거] 2026-07-30 출원관리(S_PMS_03012010) 정찰 재확인: apvStat 드롭다운 10 출원지시전 / 01 출원지시 /
 *    02 접수 / 03 처리중 / 04 제출 / 05 출원검토 / 09 완료. 선행조사 완료코드 04는 마스터 문서 실측.
 *  [미확정] ① 신청목록 응답의 ppsApvStat·ppsCmplDt 실재 여부(있으면 1순위 자동 적용, 없으면 2순위로 동작)
 *    ② pps 목록의 intellRqstNo·intellMngNo 포함 여부(부재 시 linked=false → 기존 동작 폴백)
 *    ③ 'pps행없음'(요청일은 있는데 대조 행 없음) 건수 — 진단 카운트로 실측 후 정책 재검토.
 *  [캐시] pd_cache_v27 → v28(구 캐시의 오탐 항목 잔존 방지). [안전] 조회 전용. 라우팅 무변경.
 */

/*
 * v1.18.1 (2026-07-27) — 마스터 검색 사용성 보강 (patch, 1.18.0 -> 1.18.1)
 *  [개선1] 검색기준 자동판별 확장: RESI+숫자 패턴 → 신청번호(intellRqstNo)로 검색.
 *    (기존: 관리번호 패턴 → intellMngNo, 그 외 → 발명명칭 ivenNm)
 *  [개선2] 결과 상한: 목록에는 상위 30건만 표시(대량 결과 UI 보호). 배너에
 *    '상위 30건 표시' 안내 + '마스터 화면에서 전체 보기' 링크(S_PMS_03019010 새 창).
 *  [개선3] 중복 조회 방지: 동일 검색어 Enter 재입력 시 서버 재조회 없이 캐시 재사용.
 *    로딩 중 Enter 가드(중복 요청 차단).
 *  [개선4] Esc로 마스터 결과 즉시 해제(검색창 포커스 시).
 *  [안전] 라우팅·데이터 로직 무변경. node --check 통과.
 */

/*
 * v1.18.0 (2026-07-27) — 지식재산권 마스터 전체검색 (minor revision, 1.17.5 -> 1.18.0)
 *  [기능] 전체 검색창에서 Enter → 지재권 마스터(전체 3천여건) 서버 조회. 기존 로컬(6단계
 *    수집분) 필터는 그대로 즉시 동작하고, 마스터 결과를 목록 하단 별도 섹션으로 병합.
 *  [근거] 마스터 화면(S_PMS_03019010) 검색폼 실측: item(관리번호/발명명칭/발명자 등 12종),
 *    searchDtCls(03 신청/01 출원/02 등록), searchStrDt/searchEndDt. 셀→팝업: 통합 허브
 *    S_PMS_03019020 {intellRqstNo}. 응답 68필드(ivenNm·mainIvenEmpNm·masterApvNm 등 표시 확인).
 *  [구현] runMasterSearch: 검색어가 관리번호 패턴이면 item=intellMngNo, 아니면 item=ivenNm.
 *    날짜 2000-01-01~오늘(keyword로 필터되어 부하 낮음), cls=detail, isAuthorized=Y.
 *    결과 클릭 → 통합 허브 팝업(03019020) {intellRqstNo}. 마스터 소스는 온디맨드(초기 로딩 무영향).
 *  [UX] 결과 0건 시 '주발명자로 재검색' 링크(item=mainIvenEmpNm) 제공. 검색어 변경 시 이전
 *    마스터 결과 자동 해제. placeholder에 Enter 안내 추가.
 *  [무변경] 2번(숨김→카운트 제외)은 점검 결과 이미 전 카운트에 반영되어 있어 미수정.
 *  [안전] 조회 전용(마스터 API는 read). node --check 통과.
 */

/*
 * v1.17.5 (2026-07-27) — 상단 UI 정리: 요약 제거·빠른이동 박스화(마스터 추가)·탭 1열 (patch, 1.17.4 -> 1.17.5)
 *  [수정1] 요약 스트립(포털/특허/경과 카운트) 제거 — 사용자 요청. 관련 렌더는 요소 부재 시
 *          조기 반환으로 무해(renderSummary 호출부 유지, DOM만 제거).
 *  [수정2] 빠른 이동 칩 → 박스 스타일(사각 버튼). '마스터' 항목 추가(지식재산권 마스터
 *          S_PMS_03019010 새 창) — 실측 화면 URL. 각 항목은 기존과 동일하게 해당 IPMS 화면 새 창.
 *  [수정3] 단계 탭(전체/포털/신청…청구서) 1열 고정 — 검색창을 상단 우측으로 올리고, 탭을
 *          전용 행(가로 스크롤·줄바꿈 없음)으로 분리. 상태 서브필터는 탭 아래 줄 유지.
 *  [안전] 데이터·라우팅 로직 무변경(순수 UI). node --check 통과.
 */

/*
 * v1.17.4 (2026-07-27) — 조회 기간 전 소스 서버 적용 + 패널 삽입위치 교정(가림 해결) (patch, 1.17.3 -> 1.17.4)
 *  [속도·근거] 5개 목록 화면 검색폼 날짜 필드 실측: 신청·선행조사·출원·등록·업무요청 전부
 *    rqstStrDt/rqstEndDt — 청구서와 동일 계약(yyyyMMdd). 기존 '조회 기간' 설정이 청구서에만
 *    서버 적용되고 나머지는 전량(최대 5,136행) 수신하던 것이 잔여 병목.
 *  [속도·구현] 소스별 기간 정책(판별 로직 보전을 위한 이원화):
 *    · task·file·reg: 설정 기간(rqstStrDt~오늘) 서버 조회 — 전송량 대폭 감소.
 *    · apply: 하한 7개월 보장(max(설정,7)) — '선행조사 미의뢰/출원지시 대기' 180일 창 로직 보전.
 *    · pps: 전량 유지 — 733건 소량 + 오래된 미완료 재촉 대상 보전.
 *  [속도·안전망] dateFallback: 기간 조회가 오류 없이 0건이면 파라미터 오해석 가능성으로 보고
 *    전량 재조회로 자동 폴백(최악의 경우 = 기존 동작). 진단 테이블에 from(조회 시작일) 컬럼 추가.
 *  [가림·근거] 포털 메인 body 실측(1.26MB outerHTML): main_container > con_left(.timecard
 *    '잔여근무시간' 박스가 첫 요소) · con_center(position:relative) · con_right 3컬럼.
 *    기존 'con_center 형제 삽입'은 전폭 패널이 float 좌측 컬럼(타임카드) 위를 덮음 — 가림의 원인.
 *  [가림·구현] 패널을 con_center 내부 첫 자식으로 삽입 — 중앙 컬럼 폭 안에 기하학적 격리,
 *    타임카드와 불겹침. #pd-panel max-width:100% 추가(저장된 패널 폭이 컬럼 초과 시 넘침 방지).
 *    상단 여백 설정(v1.17.2)은 범용 수단으로 유지.
 *  [기간 UI] 별도 신설 없음 — 기존 설정 '조회 기간'(1/2/3/6/12개월)이 이제 전 소스 서버 조회에
 *    실제 적용됨. 지연·기한초과 건이 안 보이면 기간을 늘려 조회(진단 from으로 확인 가능).
 *  [안전] 조회 전용. 캐시 불변(SWR로 자연 교체). node --check 통과.
 */

/*
 * v1.17.3 (2026-07-27) — 청구서 검토 myWork 진입: 포털 공식 함수 재사용 (patch, 1.17.2 -> 1.17.3)
 *  [근거] 2026-07-27 index.do 정찰(v5.3.0) 신규 실측 2건:
 *    · 포털 공식 BPM 진입 함수 fnShowWorkBpmPopup 전체 소스 확보 — (url, processCode,
 *      instanceName=bizKey, statusCode)를 받아 workFlag:'myWork' 4키 폼을 $.postWindow로 조립.
 *      index.do에 로드되어 있어 본 스크립트에서 직접 호출 가능.
 *    · B_RES00015 myWork 팝업 실측: bizKey=202607-034(실값·청구요청번호 형식), workFlag=myWork.
 *      opener/popup 파라미터 일치 확인. (statusCode ST0301은 BPM 워크리스트 정찰과 합치)
 *  [수정] 청구서 검토(04·07)+cnfRqstNo → via 'bpmFn' 신설:
 *    · 1순위: 포털 fnShowWorkBpmPopup('B_RES00015_01.do', 'B_RES00015', cnfRqstNo, 'ST0301')
 *      호출 — 파라미터 조립·창 옵션(1280×900)을 포털 원본에 위임(조립 오류 원천 차단).
 *    · 폴백: 함수 부재/실패 시 myWork 4키 폼 직접 제출(실측 계약 동일).
 *    · 기존 readOnly 진입(v1.17.0 도입)은 열람만 가능 → 처리 버튼이 뜨는 myWork로 승격.
 *  [확인 필요] statusCode 'ST0301'은 검토중 계열에서만 2회 관측 — 타 검토 하위상태의 값은
 *    미확정(정찰기 gaps 자가지목: B_RES00015 상태별 변형 1건 미완). 이상 동작 시 해당 건을
 *    포털 '나의 업무'에서 열어 F12로 statusCode 실값 확보 요망.
 *  [무관 기록] index.do dutyGrid는 당직근무표(부서/직무/담당/내선) — 대시보드 무관, 미반영.
 *  [안전] 조회 전용. 캐시 불변. node --check 통과.
 */

/*
 * v1.17.2 (2026-07-27) — 로딩 속도 구조 개선(SWR·단일샷) + 상단 가림 대응 (patch, 1.17.1 -> 1.17.2)
 *  [속도1·단일샷 페치] 대형 목록 초기 take를 2000→MAX_FULL(6000)로. 기존엔 2000 수신 후
 *    total(예: 업무요청 5,136)만큼 재요청하는 이중 페치 — 왕복 2회·중복 전송(2000+전량).
 *    동등성 근거: 기존 재요청이 pageBody(total≤6000)로 전량 수신됨을 이미 검증. 재페치 가드는
 *    폴백으로 유지(사실상 미발동). 효과: 신청·출원·등록·업무요청 4대 소스 왕복 반감, 전송 약 40%↓.
 *  [속도2·SWR] 캐시가 있으면 나이에 상관없이 즉시 렌더(체감 0초) 후, 10분 경과 시에만
 *    화면 유지한 채 백그라운드 갱신·재렌더. 기존엔 10분 지나면 빈 화면+블로킹 재조회.
 *  [속도3·계측] DIAG에 소스별 소요 ms 기록, 콘솔 진단 테이블에 ms 컬럼 — 병목 소스 정량 특정용.
 *  [가림1·상단 여백] 설정에 '상단 여백(px)'(0~400) 추가. 포털 상단 절대배치 요소(출근/퇴근·
 *    잔여근무시간 박스 등)를 패널이 덮는 경우, 패널을 그 아래로 내리는 즉효 수단.
 *  [가림2·위젯 초기화] 설정에 '위젯 레이아웃 초기화' 추가 — 과거 편집모드로 이동/확대한
 *    위젯이 박스를 덮은 경우 편집모드 진입 없이 즉시 원복(LAYOUT 초기화+원상복구).
 *  [미확정] 가림의 정밀 원인(박스 셀렉터·배치)은 포털 index.do 해당 영역 outerHTML 필요 —
 *    확보 시 자동 회피(해당 요소 아래 삽입/높이 감지)로 승격 예정. 첨부 2건은 빈 파일로 수신됨.
 *  [안전] 조회 전용. 캐시 포맷 불변(pd_cache_v27 유지). node --check 통과.
 */

/*
 * v1.17.1 (2026-07-27) — 상태 드롭다운 공식정의 정합화 + 진단부제 실명화 (patch, 1.17.0 -> 1.17.1)
 *  [근거] 2026-07-27 KM STRUCTURE 실측: 각 화면 진행상태 <select> 공식 코드→명칭 확보.
 *    이전까지 흩어진 추정 라벨을 화면 공식 정의로 통일하고, 잘못 참조하던 필드를 교정.
 *  [수정1·출원 정합성(중요)] 출원 판별을 rqstApvStat 혼용 → apvStat 단일 기준으로 교정.
 *    · 드롭다운 실측: apvStat 10=출원지시전 / 01=출원지시 / 02=접수 / 03=처리중 / 04=제출 /
 *      05=출원검토 / 09=완료. (기존 코드는 rqstApvStat 04=확인대기로 오인 — apvStat 04는 제출)
 *    · 10(출원지시전=대량)은 출원탭에서 제외 — 신청목록발 '출원지시 대기'(좁힌 조건)로만 표시(폭주 방지).
 *    · 01~05는 진행중(사무소·특허청 작업)으로 추적 표시, 09=완료 제외. 담당 처리(action)는
 *      출원지시(신청목록발)뿐 — 출원 진행 자체는 사무소 몫이므로 전부 progress.
 *  [수정2·청구서 발행완료 판정] taxbilIsuClsNm(목록에 부재) 참조 제거 → taxbilIsuCls=='Y'
 *    OR taxbilIsuDt(발행일) 존재로 판정(실측 필드). 반쪽만 작동하던 발행완료 분류 정상화.
 *  [수정3·청구서 라벨] 드롭다운 공식정의 반영: 01 접수대기 / 02 접수 / 03 검토준비중(기존
 *    '세금계산서 발행요청' 오류) / 04 검토중 / 09 계산서발행대기(사무소) / 10 지출발의대기 / 11 완료(제외).
 *  [수정4·업무요청 라벨] 드롭다운: 01 신청 / 02 접수 / 03 검토중 / 04 확인대기 / 05 완료.
 *    처리 대상 01·02·03·04(00 임시·05 완료 제외). 03·04→B_RES00012, 01·02→03014020(라우팅 무변경).
 *  [수정5·진단 부제 실명화] 청구서 부제 '[상태 NN]' → 상태명(APV_STAT 사전). 원인추적용
 *    코드표시를 사용자 가독 실명으로 전환(진단성 유지).
 *  [구조] APV_STAT 상수 신설(화면별 apvStat 공식 코드→명칭). 라벨·부제 일원화, 유지보수↑.
 *  [등록 주석] 드롭다운(01 결정보고제출…10 완료)과 행실측 statusDiff(01 접수대기중/07·12 완료)가
 *    상충 — 청구서式 표시코드/워크플로 불일치로 판단, 행실측(v1.17.0) 유지. 상충 사실 명시.
 *  [캐시] pd_cache_v26 → v27. [안전] 조회 전용. node --check 통과.
 */

/*
 * v1.17.0 (2026-07-27) — 6단계 상태·라우팅 실측 완비 (minor revision, 1.16.0 -> 1.17.0)
 *  [근거] 2026-07-27 KM 정찰 전 6화면 완료(청구서·선행조사·출원·업무요청·등록). 열기계약
 *    verified 및 상태 드롭다운·팝업 버튼 실측 확정. 이하 전부 '추정 제거·실측 반영'.
 *  [수정1·출원지시대기 라우팅] 신청(apply)에서 만들던 '출원지시 대기'를 stage=file로 push.
 *    · 실측(출원관리 col7 선행조사 셀): 출원 상세 03012020은 rqstNo 없이 {intellRqstNo}만으로 열림.
 *    · 출원지시는 별도 화면이 아니라 03012020 팝업 내 [btnApprove=출원지시] 버튼(실측).
 *    · 결과: '출원지시 대기' 클릭 시 신고서(B_RES00004)가 아니라 출원 상세로 정확히 이동.
 *      (기존엔 stage=apply라 STAGE_POPUP.apply=신고서로 폴백되어 '신청서만 뜨는' 원인).
 *  [수정2·청구서 검토 라우팅 재도입] exp 검토(04·07)+cnfRqstNo 존재 → B_RES00015 직진입.
 *    · 실측 폼: {bizKey:cnfRqstNo, workFlag:'readOnly', from:'S_PMS_03015020', accRqstNo:actRqstNo}.
 *    · cnfRqstNo 없으면 청구서 상세(03015030)로 안전 폴백. (v1.16.0의 보류 해제)
 *  [수정3·등록 완료코드] REG_DONE ['07','09'] → ['07','12'](실측: 09 미관측, 12=완료 다수).
 *    등록 검토중(04) 항목 추가(기존 누락). 01 등록결정(action)/04·06 진행중.
 *    등록완료 접수(cmplRqstApvStat 09)는 이번에도 미관측(12=완료만) — 로직 유지+주석.
 *  [수정4·업무요청 유령코드 제거] 판별 ['01','03','04'] → ['01','04'].
 *    · 실측: 목록 apvStat에 03 없음(03은 별도 축 bpmApvStat 값). apvStatNm 실측 04검토중/05·06완료.
 *    · 04→B_RES00012(BPM), 01→03014020(실측 계약). 라우팅 무변경, 판별만 교정.
 *  [수정5·구조] push에 actRqstNo 저장(B_RES00015 accRqstNo 파라미터용).
 *  [캐시] pd_cache_v25 → v26(구 캐시 오라우팅 방지).
 *  [미확정·안전폴백] ① 출원지시대기 03012020 파라미터 키(intellRqstNo 단독 가정, 폼구조상 유력)
 *    ② reg cmplRqstApvStat '09' 실재. 두 항목은 파라미터 부재 시 목록 열기로 안전 폴백.
 *  [안전] 조회 전용 유지. node --check 통과. 상태 판별은 확실 실측만 반영(오탐/누락 최소).
 */

/*
 * v1.16.0 (2026-07-27) — 상태코드 기반 팝업 라우팅 전면 교체 (minor revision, 1.15.3 -> 1.16.0)
 *  [근거] 2026-07-27 KM 정찰 실측(ipms_km_combined_*): 화면별 셀→팝업 openerParams 전수 대조.
 *    · BPM 팝업(B_RES*)의 실측 진입 패턴은 2종뿐 —
 *        목록화면 발  {bizKey, workFlag:'readOnly', from:'S_PMS_*'}
 *        워크리스트 발 {processCode, bizKey, statusCode:'ST****', workFlag:'myWork'}
 *      기존 workFlag:'work'는 실측에 존재하지 않는 값 → BPM 분기 실패의 유력 원인.
 *    · myWork 진입 필수인 statusCode(ST0103/ST0301/ST0500…)는 IPMS 목록 응답에 없음
 *      → 목록 데이터만으로는 myWork 진입 불가. 실측 확정 패턴(readOnly)으로 교정.
 *  [수정1·라우팅] resolvePopup: 라벨 정규식(/검토/ 등) → (단계, 상태코드) 분기로 교체.
 *    · '청구서 접수 완료 (검토 대기)'(02) 등 라벨이 /검토/에 오매칭되어 B_RES00015로
 *      가던 문제 해소. 라벨 문안을 바꿔도 라우팅이 깨지지 않음.
 *    · exp: 10(발의대기)→03015040 {rqstNo}, 그 외 전부→03015030 {rqstNo} (실측 ✓).
 *      B_RES00015 직진입은 목록화면 발 파라미터 미실측(그리드 bpmBtn 열)으로 제거 —
 *      F12 실측 확보 후 재도입(resolvePopup 내 주석 참조).
 *    · task: 03·04(BPM 단계)→B_RES00012 {bizKey:bpmRqstNo, workFlag:'readOnly', from}(실측
 *      패턴), 그 외(01 등)→03014020 {rqstNo} (실측 ✓).
 *    · reg: cmplRqstApvStat 09→03013030 {rqstNo}, 그 외→03013020 {rqstNo, intellRqstNo} (실측 ✓).
 *  [수정2·필드] 등록완료 bizKey 필드명 교정: cmplRqstNo(응답에 부재) → intellRegCmplRqstNo(실측).
 *    기존엔 undefined 폴백으로 등록결정 rqstNo가 03013030에 전달되던 오류.
 *    F.stageRqstNo.reg의 유령 필드(regRqstNo·cmplRqstNo) 제거 → ['rqstNo','intellRegDecsnRqstNo'].
 *  [수정3·구조] push()에 원시 상태코드 저장: st(단계 상태, file은 rqstApvStat 우선)·cmplSt·taxDone.
 *  [캐시] 구 캐시 acts에 st 부재 → 오라우팅 방지 위해 캐시 키 갱신(pd_cache_v25).
 *  [확인 필요] ① B_RES00015 목록화면 발 진입 파라미터(bpmBtn 열 더블클릭 실측)
 *    ② reg cmplRqstApvStat '09'는 이번 정찰 미관측(12=완료만 실측) — F12 실재 확인.
 *  [안전] 조회 전용 유지. readOnly 진입은 열람용 — 처리 버튼이 없으면 포털 '나의 업무'에서 처리.
 */

/*
 * v1.15.1 (2026-07-16) — 긴급복구 신뢰성 + 접힘 시 설정메뉴 클리핑 + 연차료 카드 제거 (minor revision, 1.15.0 -> 1.15.1)
 *  [수정1·긴급복구] 킬스위치(Alt+Shift+X) 후 재활성화가 안 되던 문제 보강.
 *         · 재활성화 시 gmSet(K.disabled,false)를 최우선 실행(리로드/재호출 안전).
 *         · 잔여 [data-pd] 요소(스타일·토스트 등) 제거 후 재부팅 -> 중복 패널/스타일 방지.
 *         · 렌더 상태(MODEL/ANN/PORTAL/RAW) 초기화 후 boot(). 각 단계 try/catch로 실패 격리.
 *         · 비활성화 안내 토스트에도 data-pd 부여(정리 일관성).
 *  [수정2·설정메뉴] 대시보드를 접은 뒤 다시 펼치려 할 때 '설정 ▾' 드롭다운이 패널 박스
 *         밖으로 나오지 못해 클릭 불가하던 문제 수정. 원인: #pd-panel의 overflow:hidden이
 *         절대배치 드롭다운(.pd-menu)을 잘라냄(접힘 상태에선 패널 높이가 툴바만큼이라 특히 심함).
 *         -> #pd-panel overflow:hidden -> overflow:visible. (리사이즈 핸들은 개별 요소라 영향 없음)
 *  [수정3·연차료 제거] 연차료 납부 카드를 제거하고 오른쪽 컬럼을 빈 플레이스홀더 카드로 유지
 *         (다음 버전에서 채울 예정). 요약 스트립의 '연차료' 셀도 제거(이동 대상 없음).
 *         loadAll의 renderPay() 호출 2곳 제거. renderPay 함수 자체는 미사용으로 남겨둠(무해).
 *         ANN 로딩은 v1.14.1에서 이미 비활성 상태였음.
 *  [캐시] 연차 캐시 잔재 제거 위해 캐시 키 갱신(pd_cache_v24).
 *  [안전] 기존 함수·데이터 흐름 미변경(제거·보강만). 조회 전용. node --check 문법검증 통과.
 */

/*
 * v1.15.0 (2026-07-05) — 기간별 통계(신청·출원·등록) CSV 추출 추가 (minor revision, 1.14.1 -> 1.15.0)
 *  [추가] 설정 -> '기간별 통계 (CSV)': 신청/출원/등록 목록 API 조회 후 기간(주/월/분기/연) 단위 건수 집계.
 *         국가별·상태별 분해 옵션, 기간 범위(시작~종료) 지정. BOM 포함 CSV(엑셀 한글 호환).
 *  [데이터] apply(selectIntellpptyList) / file(selectAplyRqstList) / reg(selectIntellRegRqstList).
 *          날짜기준: 신청 rqstDt / 출원 aplyDt / 등록 regDt->intellRegDt->regDecsnDt(폴백).
 *          날짜 없는 건(미출원·미등록 등)은 자동 제외하고, 제외 건수를 CSV 상단에 표기(자가 진단).
 *  [주의] apvStat 코드 의미는 탭마다 다름 -> 상태 분해는 카테고리(신청/출원/등록)별로 구분 집계.
 *  [구조] loadAll의 원시 rows를 RAW로 보관(메모리)하여 재조회 없이 집계. 없으면 3개 API만 조회.
 *  [안전] 기존 함수·선언 미변경(추가만). 조회 전용(쓰기 API 미사용). node --check 문법검증 통과.
 */


