    if (a.stage === 'task' && pc === 'B_RES00012') a.action = (sc === 'ST0103') ? '박사 검토완료 → 특허사무소 전달' : ('업무요청 · 내 차례' + (sn ? ' (' + sn + ')' : ''));
    else if (a.stage === 'exp' && pc === 'B_RES00015') a.action = '청구서 검토 · 내 차례' + (sn ? ' (' + sn + ')' : '');
    else if (a.stage === 'apply' && pc === 'B_RES00004') a.action = '지재권 신청 · 내 차례' + (sn ? ' (' + sn + ')' : '');
    else if (a.stage === 'file' && pc === 'B_RES00011') a.action = '출원 업무 · 내 차례' + (sn ? ' (' + sn + ')' : '');
