    if (/지식재산|특허|선행조사|출원|등록|청구서|연차유지|업무요청/.test(text)) {
      return { stage: 'task', label: '미분류 특허 BPM (' + (pc || '코드없음') + ')', url: w.ext2 || w.inittaskid || '' };
    }
    /* v1.25.7: 여기서 null을 돌려주면 그 나의업무는 어느 목록에도 나타나지 않는다(실측 3건 증발).
     * 특허 키워드에 안 걸리는 업무도 '기타' 단계로 올린다 — 누락이 오분류보다 나쁘다. */
    if (gmGet(K.allbpm, true)) {
      return { stage: 'etc', label: (String((w && w.defname) || '').trim() || ('BPM ' + (pc || '코드없음'))), url: (w && (w.ext2 || w.inittaskid)) || '' };
    }
