        baseAction: meta.label + ' · 내 차례 (BPM 직접)', nm: [w.subject, w.info, sn].filter(Boolean).join(' · '),
        due: null, elapsed: null, track: 'action', baseTrack: 'action', myWork: wp, orphanBpm: true, mine: true,
